data.CSS:
@font-face { font-family:"Fraunces"; font-weight:600; font-display:swap; src:url("/fonts/fraunces-600.woff2") format("woff2"); }
@font-face { font-family:"Inter"; font-weight:400; font-display:swap; src:url("/fonts/inter-400.woff2") format("woff2"); }
@font-face { font-family:"Inter"; font-weight:600; font-display:swap; src:url("/fonts/inter-600.woff2") format("woff2"); }
:root { --paper:#F5F2ED; --stone:#EAE4DA; --ink:#1F1E1C; --muted:#57534D; --rule:#D9D2C7; --clay:#9A4A2A; --clay-dark:#7A3A20; --sage:#4F5C47;
  --display:"Fraunces", Georgia, serif; --body:"Inter", system-ui, sans-serif; }
* { box-sizing:border-box; }
body { margin:0; background:var(--paper); color:var(--ink); font:16.5px/1.65 var(--body); }
img { display:block; max-width:100%; height:auto; }
a { color:var(--clay); text-underline-offset:.2em; }
a:hover { color:var(--clay-dark); }
h1, h2, h3 { font-weight:600; line-height:1.15; margin:0 0 .6em; color:var(--ink); }
h1 { font-family:var(--display); font-size:clamp(2.2rem, 4.6vw, 3.6rem); letter-spacing:-.01em; }
h2 { font-size:clamp(1.35rem, 2.2vw, 1.7rem); letter-spacing:-.015em; }
h3 { font-size:1.1rem; letter-spacing:-.01em; }
.t-wrap { max-width:74rem; margin:0 auto; padding:0 1.5rem; }
.t-narrow { max-width:46rem; }
.t-skip { position:absolute; left:1rem; top:-3rem; z-index:10; background:var(--ink); color:var(--paper); padding:.5rem 1rem; font-weight:600; }
.t-skip:focus { top:1rem; }
.t-header { border-bottom:1px solid var(--rule); }
.t-header .t-wrap { display:flex; flex-wrap:wrap; align-items:baseline; gap:.75rem 2.5rem; padding-top:1.4rem; padding-bottom:1.2rem; }
.t-brand { font-family:var(--display); font-weight:600; font-size:1.6rem; color:var(--ink); text-decoration:none; }
.t-brand span { font-family:var(--body); font-size:.72rem; font-weight:600; letter-spacing:.18em; text-transform:uppercase; color:var(--muted); margin-left:.6rem; }
.t-nav ul, .t-langs { display:flex; flex-wrap:wrap; gap:.25rem 1.6rem; list-style:none; margin:0; padding:0; }
.t-nav a { color:var(--ink); text-decoration:none; font-size:.95rem; }
.t-nav a:hover, .t-nav a[aria-current=page] { text-decoration:underline; text-decoration-color:var(--clay); text-decoration-thickness:2px; text-underline-offset:.45em; }
.t-nav a.is-ancestor { text-decoration:underline; text-decoration-color:var(--rule); text-decoration-thickness:2px; text-underline-offset:.45em; }
.t-langs { margin-left:auto; font-size:.8rem; }
.t-langs a { color:var(--muted); text-decoration:none; text-transform:uppercase; letter-spacing:.12em; font-weight:600; }
.t-langs a:hover { color:var(--clay); }
.t-hero { padding:4rem 0 3.5rem; }
.t-hero .t-wrap { display:grid; gap:2.5rem 3rem; grid-template-columns:minmax(0, 5fr) minmax(0, 7fr); align-items:end; }
.t-hero p { font-size:1.15rem; color:var(--muted); max-width:30rem; margin:0 0 1.75rem; }
.t-hero img { width:100%; aspect-ratio:16/10; object-fit:cover; }
.t-button { display:inline-block; background:var(--ink); color:var(--paper); font-weight:600; text-decoration:none; padding:.8rem 1.5rem; letter-spacing:.01em; }
.t-button:hover { background:var(--clay-dark); color:var(--paper); }
button.t-button { border:0; cursor:pointer; font:inherit; font-weight:600; }
.t-section { padding:4rem 0; }
.t-section + .t-section { border-top:1px solid var(--rule); }
.t-band { background:var(--stone); }
.t-lead { font-size:1.2rem; color:var(--muted); max-width:44rem; }
.t-cards { display:grid; gap:2.5rem 2rem; grid-template-columns:repeat(auto-fill, minmax(18rem, 1fr)); list-style:none; margin:2rem 0 0; padding:0; }
.t-cards-row { grid-template-columns:repeat(auto-fit, minmax(18rem, 1fr)); }
.t-card img { aspect-ratio:4/3; object-fit:cover; width:100%; margin-bottom:1rem; }
.t-card h2, .t-card h3 { font-size:1.2rem; margin-bottom:.3rem; }
.t-card a { color:var(--ink); text-decoration:none; }
.t-card a:hover { color:var(--clay); text-decoration:underline; }
.t-card p { margin:0; color:var(--muted); }
.t-grid { display:grid; gap:2rem; grid-template-columns:repeat(auto-fit, minmax(14rem, 1fr)); list-style:none; margin:2rem 0 0; padding:0; }
.t-grid li { border-top:2px solid var(--ink); padding-top:1rem; }
.t-grid p { margin:0; color:var(--muted); }
.t-split { display:grid; gap:3rem; grid-template-columns:minmax(0, 3fr) minmax(0, 2fr); align-items:start; }
.t-facts { display:grid; grid-template-columns:auto 1fr; gap:.6rem 1.5rem; margin:0 0 1.5rem; padding:1.5rem 0; border-top:2px solid var(--ink); border-bottom:1px solid var(--rule); }
.t-facts dt { font-size:.78rem; font-weight:600; letter-spacing:.12em; text-transform:uppercase; color:var(--muted); padding-top:.2em; }
.t-facts dd { margin:0; }
.t-figure { margin:0 0 2.5rem; }
.t-figure img { width:100%; }
.t-figure figcaption { font-size:.88rem; color:var(--muted); margin-top:.6rem; }
.t-prose p, .t-prose ul { margin:0 0 1.1rem; }
.t-page section { margin:0 0 3.5rem; }
.t-member { display:grid; gap:2rem; grid-template-columns:minmax(0, 2fr) minmax(0, 3fr); align-items:start; }
.t-role { font-size:.8rem; font-weight:600; letter-spacing:.12em; text-transform:uppercase; color:var(--clay); margin:-.2rem 0 1rem; }
.t-contact { display:flex; flex-wrap:wrap; gap:1.5rem 3rem; align-items:center; justify-content:space-between; }
.t-contact p { margin:0; max-width:36rem; color:var(--muted); font-size:1.1rem; }
.t-form { display:grid; gap:1rem; max-width:36rem; margin-top:1.5rem; }
.t-field { margin:0; }
.t-field label { display:block; font-weight:600; margin-bottom:.3rem; }
.t-field input, .t-field textarea { width:100%; padding:.65rem .8rem; font:inherit; color:var(--ink); background:#fff; border:1px solid var(--rule); border-radius:0; }
.t-field input:focus, .t-field textarea:focus { outline:2px solid var(--clay); outline-offset:1px; }
.t-field textarea { min-height:9rem; }
.t-footer { border-top:1px solid var(--rule); padding:2.5rem 0 3rem; margin-top:2rem; font-size:.92rem; color:var(--muted); }
.t-footer .t-wrap { display:flex; flex-wrap:wrap; justify-content:space-between; gap:1rem; }
.t-footer p { margin:0; }
.t-footer .t-mark { font-family:var(--display); font-weight:600; color:var(--ink); font-size:1.1rem; }
@media (max-width: 48rem) { .t-hero .t-wrap, .t-split, .t-member { grid-template-columns:1fr; } .t-langs { margin-left:0; } .t-hero { padding:2.5rem 0; } .t-section { padding:3rem 0; } }
